# --- اكتشاف مفتاح مادة التاريخ للرابعة متوسط في db.js ---
LV=$(tr -d '\n' < db.js | sed 's/"name": *"السنة/\n&/g' | grep 'السنة الرابعة متوسط' | head -1)
KEY=""
for k in hist history histoire tarikh; do
  if printf '%s' "$LV" | grep -q "\"$k\": *{\"links\""; then KEY=$k; break; fi
done
if [ -z "$KEY" ]; then
  printf '%s' "$LV" | head -c 3000 > ~/storage/downloads/h4_diag.txt
  echo "لم أجد مادة التاريخ للرابعة متوسط في db.js. كتبتُ تشخيصا في التنزيلات: h4_diag.txt - أرسله لي."
  echo "لم يُربط شيء بالتطبيق بعد (الملفات الجديدة فقط في www)."
  exit 1
fi
echo "مفتاح المادة: $KEY"
sed -i "s/__KEY__/$KEY/" lessons_4am_hist.js

# --- ربط الملفات في index.html (مرة واحدة فقط) ---
if ! grep -q 'lessons_4am_hist.js' index.html; then
  LN=$(grep -n '<script src="lessons' index.html | tail -1 | cut -d: -f1)
  if [ -n "$LN" ]; then
    sed -i "${LN}a <script src=\"h4_data.js\"></script>\n<script src=\"lessons_4am_hist.js\"></script>" index.html
  else
    echo "تنبيه: لم أجد وسوم lessons في index.html"
  fi
fi
if ! grep -q 'maps_h4_hook.js' index.html; then
  if grep -q 'maps_i4_hook.js' index.html; then
    sed -i '/maps_i4_hook.js/a <script src="maps_h4_hook.js"></script>' index.html
  elif grep -q 'maps_n4_hook.js' index.html; then
    sed -i '/maps_n4_hook.js/a <script src="maps_h4_hook.js"></script>' index.html
  elif grep -q 'maps_p4_hook.js' index.html; then
    sed -i '/maps_p4_hook.js/a <script src="maps_h4_hook.js"></script>' index.html
  elif grep -q 'maps_m4_hook.js' index.html; then
    sed -i '/maps_m4_hook.js/a <script src="maps_h4_hook.js"></script>' index.html
  else
    sed -i '/maps_hg_hook.js/a <script src="maps_h4_hook.js"></script>' index.html
  fi
fi

echo "---- تحقق ----"
ls -l h4_data.js lessons_4am_hist.js maps_h4.html maps_h4_hook.js
grep -n 'h4_data.js\|lessons_4am_hist.js\|maps_h4_hook.js' index.html
echo "تم. نسخة احتياطية: index.html.bak_h4"
echo "ثم: cd ~/zad-1am && git add -A && git commit -m 'History 4AM part 1' && git push origin main"
